def calculate_discount(price: float, user_type: str) -> float:
    """Calculate discount based on user membership."""
    if price <= 0:
        raise ValueError('Price must be positive')
    if user_type == 'premium':
        return price * 0.20
    elif user_type == 'member':
        return price * 0.10
    return 0.0

