const generation = $('Agent 2 — Generator (LLM)').item.json;
const quality = $('Agent 3 — Validator (Quality Score)').item.json;
const mutations = $('Agent 4 — Refiner (Mutation Testing)').item.json;
const behaviors = $('Agent 1 — Analyzer (Behaviors)').item.json;
const complexity = $('Agent 1 — Analyzer (Complexity)').item.json;
const coverage = $('Agent 5 — Coverage Mapper (Gaps)').item.json;
const security = $('Security Scanner (OWASP)').item.json;

return [{
  json: {
    run_id: generation.run_id,
    status: 'completed',
    summary: {
      quality_grade: generation.quality?.grade || quality.grade,
      quality_score: generation.quality?.overall || quality.overall,
      tests_generated: generation.syntax_validation?.test_count || 0,
      behaviors_extracted: behaviors.total_behaviors || 0,
      behavior_coverage_pct: coverage.coverage_pct || generation.behavior_coverage?.coverage_pct || 0,
      uncovered_behaviors: coverage.gaps?.length || 0,
      mutation_score_pct: mutations.mutation_score || generation.mutation_testing?.mutation_score || 0,
      mutants_killed: mutations.killed_count || generation.mutation_testing?.killed || 0,
      mutants_survived: mutations.surviving_count || generation.mutation_testing?.survived || 0,
      iterations_performed: generation.iterations_performed || 1,
      processing_time_s: (generation.processing_time_ms / 1000).toFixed(1),
      complexity_grade: complexity.grade,
      functions_analyzed: complexity.total_functions || 0,
      security_issues: security.vulnerabilities?.length || 0,
      security_risk: security.risk_level || 'low'
    },
    test_code: generation.test_code,
    test_files: generation.test_files || [],
    coverage_gaps: coverage.gaps || [],
    security_findings: security.vulnerabilities || [],
    pipeline_stages: [
      { stage: '1. Analyzer',  status: 'done', output: `${behaviors.total_behaviors || 0} behaviors extracted, complexity ${complexity.grade}` },
      { stage: '2. Generator', status: 'done', output: `${generation.syntax_validation?.test_count || 0} tests generated` },
      { stage: '3. Validator', status: 'done', output: `Grade ${generation.quality?.grade || quality.grade || '?'} — ${generation.quality?.overall || quality.overall || 0}/100` },
      { stage: '4. Refiner',   status: 'done', output: `${mutations.killed_count || 0} mutants killed, score ${mutations.mutation_score || 0}%` },
      { stage: '5. Mapper',    status: 'done', output: `${coverage.coverage_pct || 0}% covered, ${coverage.gaps?.length || 0} gaps` },
      { stage: 'Security',     status: 'done', output: `${security.vulnerabilities?.length || 0} issues, risk: ${security.risk_level || 'low'}` }
    ]
  }
}];
